1	/**
2	 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
3	 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
4	 */
5	
6	import { SANDBOX } from "./sandbox";
7	import { getSettingInt } from "./settings";
8	
9	export function registrarConfigured(): boolean {
10	  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
11	}
12	
13	/**
14	 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
15	 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
16	 * exercised end to end without touching the registrar or a real domain.
17	 */
18	export function transfersAvailable(): boolean {
19	  return SANDBOX || registrarConfigured();
20	}
21	
22	function baseUrl(): string {
23	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
24	}
25	
26	function authHeader(): string {
27	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
28	  return "Basic " + Buffer.from(raw).toString("base64");
29	}
30	
31	async function nc(
32	  method: string,
33	  path: string,
34	  body?: unknown,
35	  opts?: { nullOn404?: boolean }
36	): Promise<any> {
37	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
38	  const res = await fetch(`${baseUrl()}${path}`, {
39	    method,
40	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
41	    body: body ? JSON.stringify(body) : undefined,
42	    signal: AbortSignal.timeout(30_000),
43	  });
44	  const text = await res.text();
45	  let json: any = {};
46	  try {
47	    json = text ? JSON.parse(text) : {};
48	  } catch {
49	    /* non-JSON error body */
50	  }
51	  if (!res.ok) {
52	    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
53	    // that has already dropped off the registrar's list) — let them opt in to a
54	    // null instead of an exception rather than string-matching an error message.
55	    if (opts?.nullOn404 && res.status === 404) return null;
56	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
57	    throw new Error(`name.com: ${msg}`);
58	  }
59	  return json;
60	}
61	
62	const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));
63	
64	/** Fallback markup when no admin setting is saved. Matches the old hardcoded value. */
65	const DEFAULT_MARKUP_PCT = 25;
66	
67	/**
68	 * Platform markup over the registrar's cost, as a percentage.
69	 *
70	 * MONEY BUG (fixed 2026-07-26): Settings → Domains writes `domain_markup_percent`
71	 * and displays it, but NOTHING read it — the only references were the stored
72	 * default, the save whitelist, and the admin input itself. Meanwhile this function
73	 * read `DOMAIN_MARKUP_PCT`, which is not set in `.env`, so every domain price
74	 * silently carried the hardcoded 25%. The panel therefore showed an operator **0%**
75	 * while customers were charged **25%**, and editing the field changed nothing.
76	 *
77	 * The admin setting is now the source of truth, with the env var as the fallback so
78	 * an operator who had set it keeps their behaviour. The stored default is corrected
79	 * from "0" to 25 so the panel states what is genuinely applied — displaying 0% while
80	 * charging 25% is precisely the class of untruth this codebase keeps producing.
81	 *
82	 * Safe to change now: zero domains have been sold and the setting had never been
83	 * saved, so no customer's price moves as a result of this fix.
84	 *
85	 * Async because it reads a setting. Callers resolve it ONCE and pass it into
86	 * `retailCents`, which stays pure so the arithmetic is trivially checkable.
87	 */
88	export async function domainMarkupPct(): Promise<number> {
89	  const envDefault = Number(process.env.DOMAIN_MARKUP_PCT ?? DEFAULT_MARKUP_PCT);
90	  const pct = await getSettingInt("domain_markup_percent", envDefault);
91	  // Clamp: a free-text admin field that multiplies every domain price. A stray
92	  // keystroke must not be able to bill a customer 5000% of cost.
93	  return Math.min(Math.max(Number.isFinite(pct) ? pct : envDefault, 0), 500);
94	}
95	
96	/** Retail (customer) price for a registrar cost at `pct` markup. Pure. */
97	export function retailCents(costCents: number | null, pct: number): number | null {
98	  if (costCents === null) return null;
99	  return Math.round(costCents * (1 + pct / 100));
100	}
101	
102	export type DomainCheck = {
103	  domain: string;
104	  available: boolean;
105	  premium: boolean;
106	  priceCents: number | null; // RETAIL — what the customer pays (per year)
107	  costCents: number | null; // registrar cost (per year)
108	  renewCents: number | null; // RETAIL renewal price
109	};
110	
111	export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
112	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
113	  // Resolved ONCE for the whole batch: one settings read, and every price in a
114	  // single response is guaranteed to use the same markup.
115	  const pct = await domainMarkupPct();
116	  return (json.results ?? []).map((r: any) => {
117	    const cost = dollarsToCents(r.purchasePrice);
118	    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
119	    return {
120	      domain: r.domainName,
121	      available: r.purchasable === true,
122	      premium: r.premium === true,
123	      priceCents: retailCents(cost, pct),
124	      costCents: cost,
125	      renewCents: retailCents(renewCost, pct),
126	    };
127	  });
128	}
