156	/**
157	 * name.com's OWN auto-renew flag on the domain resource — entirely separate
158	 * from this platform's `Domain.autoRenew` column, and NOT settable on the
159	 * CreateDomain request itself (confirmed against name.com's own API docs).
160	 * Real risk found live (2026-08-29): if name.com's own default for an
161	 * API-registered domain is enabled, name.com can independently renew (and
162	 * charge NXEON'S reseller account, not the customer) on ITS OWN schedule —
163	 * regardless of what the customer chose here, including a domain they
164	 * explicitly turned auto-renew off for, or one whose owner has no wallet
165	 * funds. Disabling it after every register/renew makes
166	 * worker/billing.ts's domainAutoRenewSweep the ONLY thing that ever
167	 * initiates a renewal. Best-effort: must never fail a registration/renewal
168	 * that already succeeded and was already charged — a dangling
169	 * autorenew-enabled domain is a real ops risk to catch via this log line,
170	 * not a reason to unwind money that already moved.
171	 */
172	async function disableRegistrarAutorenew(domain: string): Promise<void> {
173	  try {
174	    await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:disableAutorenew`);
175	  } catch (e) {
176	    console.error(`[registrar] failed to disable name.com's own auto-renew for ${domain} — it may renew/charge independently of our sweep`, e);
177	  }
178	}
