218	// ---------- Nameservers / registrar lock / outbound-transfer auth code ----------
219	//
220	// Consolidated out of lib/actions-domains-advanced.ts and
221	// lib/actions-domains-dns.ts, which each had their own private name.com
222	// client hitting these same endpoints. `lockDomain`/`unlockDomain` are
223	// shared by both files: advanced.ts's outbound-transfer flow only ever
224	// unlocks, dns.ts's registrar-lock toggle does both.
225	
226	export async function setNameservers(domain: string, nameservers: string[]): Promise<void> {
227	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:setNameservers`, { nameservers });
228	}
