230	export async function lockDomain(domain: string): Promise<void> {
231	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:lock`, {});
232	}
233	
234	export async function unlockDomain(domain: string): Promise<void> {
235	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:unlock`, {});
236	}
237	
238	/** Current registrar-lock state, read straight off the domain resource. */
239	export async function isDomainLocked(domain: string): Promise<boolean> {
240	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
241	  return json?.locked === true;
242	}
243	
244	/** EPP/auth code for an outbound transfer. Null when the registrar has none to give. */
245	export async function getAuthCode(domain: string): Promise<string | null> {
246	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getAuthCode`);
247	  return json?.authCode ? String(json.authCode) : null;
248	}
249	
250	// ---------- Inbound transfers (transfer-in) ----------
251	//
252	// name.com v4 transfers:
253	//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
254	//   GET  /v4/transfers                      -> { transfers: [...] }
255	//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
256	//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
257	//
258	// A transfer always includes a 1-year extension of the registration, which is
259	// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
260	// registration rate.
261	
262	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
263	const SANDBOX_APPROVAL_MS = 2 * 60_000;
264	const SANDBOX_REGISTRY_MS = 5 * 60_000;
265	
266	/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
267	function sandboxTldCostCents(domain: string): number {
268	  const tld = domain.slice(domain.lastIndexOf(".") + 1);
269	  let h = 0;
270	  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
271	  return 900 + (h % 21) * 50; // $9.00 – $19.00
272	}
273	
274	export type TransferCheck = {
275	  domain: string;
276	  /** True when we believe an inbound transfer can be submitted for this name. */
277	  transferable: boolean;
278	  /** Plain-English reason when `transferable` is false. */
279	  reason: string | null;
280	  premium: boolean;
281	  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
282	  priceCents: number | null;
283	  /** Registrar cost we pay name.com (what we send as `purchasePrice`). */
284	  costCents: number | null;
285	};
286	
287	/**
288	 * The registrar cost of transferring `domain`, in integer cents.
289	 *
290	 * Transfers are billed at the TLD's renewal rate. name.com only reliably prices
291	 * a name it can see, so we try three sources in order and give up honestly:
292	 *   1. the availability result for the domain itself,
293	 *   2. the per-domain pricing endpoint,
294	 *   3. a throwaway probe name on the same TLD — TLD pricing is per-TLD, so an
295	 *      unregistered sibling quotes the same renewal rate.
296	 */
297	async function transferCostCents(domain: string, availability: any): Promise<number | null> {
298	  const own = dollarsToCents(availability?.renewalPrice ?? availability?.purchasePrice);
299	  if (own !== null && own > 0) return own;
300	
301	  try {
302	    const p = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getPricing`);
303	    const quoted = dollarsToCents(p?.transferPrice ?? p?.renewalPrice ?? p?.purchasePrice);
304	    if (quoted !== null && quoted > 0) return quoted;
305	  } catch {
306	    /* endpoint unavailable for this TLD/account — fall through to the probe */
307	  }
308	
309	  const tld = domain.slice(domain.indexOf(".") + 1);
310	  try {
311	    const probe = `nxeon-price-probe-${Math.random().toString(36).slice(2, 10)}.${tld}`;
312	    const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [probe] });
313	    const r = (json.results ?? [])[0];
314	    const c = dollarsToCents(r?.renewalPrice ?? r?.purchasePrice);
315	    if (c !== null && c > 0) return c;
316	  } catch {
317	    /* registrar unhappy — no price, caller surfaces that plainly */
318	  }
319	  return null;
320	}
321	
322	/**
323	 * Can this domain be transferred in, and what would it cost? Never throws for a
324	 * "no" answer — a non-transferable name comes back with `transferable: false`
325	 * and a reason the customer can act on.
326	 */
327	export async function checkTransfer(domain: string): Promise<TransferCheck> {
328	  if (SANDBOX) {
329	    // Synthetic: everything is transferable except names containing "locked",
330	    // which exercise the rejected-quote path in staging.
331	    const cost = sandboxTldCostCents(domain);
332	    if (domain.includes("locked")) {
333	      return {
334	        domain,
335	        transferable: false,
336	        reason: "This domain is locked at its current registrar. Unlock it there and try again.",
337	        premium: false,
338	        priceCents: null,
339	        costCents: null,
340	      };
341	    }
342	    return {
343	      domain,
344	      transferable: true,
345	      reason: null,
346	      premium: false,
347	      priceCents: retailCents(cost, await domainMarkupPct()),
348	      costCents: cost,
349	    };
350	  }
351	
352	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [domain] });
353	  const r = (json.results ?? [])[0];
354	  if (!r) {
355	    return {
356	      domain,
357	      transferable: false,
358	      reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.",
359	      premium: false,
360	      priceCents: null,
361	      costCents: null,
362	    };
363	  }
364	  // Purchasable means nobody owns it — there is nothing to transfer.
365	  if (r.purchasable === true) {
366	    return {
367	      domain,
368	      transferable: false,
369	      reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.",
370	      premium: r.premium === true,
371	      priceCents: null,
372	      costCents: null,
373	    };
374	  }
375	  if (r.premium === true) {
376	    return {
377	      domain,
378	      transferable: false,
379	      reason: "Premium domains can't be transferred in automatically — contact support.",
380	      premium: true,
381	      priceCents: null,
382	      costCents: null,
383	    };
384	  }
385	
386	  const cost = await transferCostCents(domain, r);
387	  if (cost === null) {
388	    return {
389	      domain,
390	      transferable: false,
391	      reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.",
392	      premium: false,
393	      priceCents: null,
394	      costCents: null,
395	    };
396	  }
397	  return {
398	    domain,
399	    transferable: true,
400	    reason: null,
401	    premium: false,
402	    priceCents: retailCents(cost, await domainMarkupPct()),
403	    costCents: cost,
404	  };
405	}
406	
407	export type TransferInfo = {
408	  domain: string;
409	  /** Raw registrar status, shown to the customer verbatim. */
410	  status: string;
411	  /** Where the losing registrar sent the approval email (not every TLD sends one). */
412	  email: string | null;
413	};
414	
415	/**
416	 * Submit an inbound transfer. `purchaseCents` is the registrar COST (integer
417	 * cents) — the same "what we expect to pay" contract `registerDomain` uses.
418	 * The auth code is passed straight through and never logged.
419	 */
420	export async function createTransfer(
421	  domain: string,
422	  authCode: string,
423	  purchaseCents: number
424	): Promise<TransferInfo> {
425	  if (SANDBOX) {
426	    // Names containing "fail" reject at submit time so staging can exercise the
427	    // "registrar refused, customer not charged" path.
428	    if (domain.includes("fail")) throw new Error("name.com: transfer rejected by the registry (sandbox)");
429	    return { domain, status: "pendingOwnerApproval", email: `owner@${domain}` };
430	  }
431	  const json = await nc("POST", "/v4/transfers", {
432	    domainName: domain,
433	    authCode,
434	    privacyEnabled: true,
435	    purchasePrice: purchaseCents / 100,
436	  });
437	  const t = json?.transfer ?? json ?? {};
438	  return {
439	    domain: t.domainName ?? domain,
440	    status: String(t.status ?? "pending"),
441	    email: t.email ? String(t.email) : null,
442	  };
443	}
444	
445	/**
446	 * Current state of an inbound transfer. Returns null when the registrar has no
447	 * transfer for this domain — which is a NORMAL answer once a transfer settles
448	 * and drops off the list, so callers must resolve that against `domainInfo`
449	 * rather than treating it as a failure.
450	 *
451	 * `startedAt` is only read in SANDBOX, where it drives a synthetic progression
452	 * (registrar.ts holds no state of its own).
453	 */
454	export async function getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null> {
455	  if (SANDBOX) {
456	    const age = Date.now() - (startedAt?.getTime() ?? Date.now());
457	    const status =
458	      age < SANDBOX_APPROVAL_MS
459	        ? "pendingOwnerApproval"
460	        : age < SANDBOX_REGISTRY_MS
461	          ? "pendingRegistry"
462	          : "completed";
463	    return { domain, status, email: `owner@${domain}` };
464	  }
465	  const t = await nc("GET", `/v4/transfers/${encodeURIComponent(domain)}`, undefined, { nullOn404: true });
466	  if (!t) return null;
467	  return {
468	    domain: t.domainName ?? domain,
469	    status: String(t.status ?? "pending"),
470	    email: t.email ? String(t.email) : null,
471	  };
472	}
473	
474	/**
475	 * Ask the registrar to cancel an in-flight inbound transfer. Throws if the
476	 * registrar refuses (e.g. the transfer already completed at the registry) —
477	 * callers must NOT credit the customer unless this resolves.
478	 */
479	export async function cancelTransfer(domain: string): Promise<TransferInfo> {
480	  if (SANDBOX) return { domain, status: "cancelled", email: null };
481	  const t = await nc("POST", `/v4/transfers/${encodeURIComponent(domain)}:cancel`, {});
482	  return {
483	    domain: t?.domainName ?? domain,
484	    status: String(t?.status ?? "cancelled"),
485	    email: t?.email ? String(t.email) : null,
486	  };
487	}
488	
489	/** All inbound transfers on the reseller account (ops/debug — not used per-domain). */
490	export async function listTransfers(): Promise<TransferInfo[]> {
491	  if (SANDBOX) return [];
492	  const json = await nc("GET", "/v4/transfers");
493	  return (json.transfers ?? []).map((t: any) => ({
494	    domain: t.domainName,
495	    status: String(t.status ?? "pending"),
496	    email: t.email ? String(t.email) : null,
497	  }));
498	}
499	
500	/** Bucket a raw registrar transfer status into something we can act on. */
501	export function transferOutcome(status: string): "completed" | "failed" | "pending" {
502	  const s = status.toLowerCase();
503	  if (/(complete|success|transferred)/.test(s)) return "completed";
504	  if (/(cancel|reject|denied|fail|expired|refund|void)/.test(s)) return "failed";
505	  return "pending";
506	}
507	
508	/** Human label for a raw registrar transfer status. */
509	export function transferStatusLabel(status: string): string {
510	  const s = status.toLowerCase();
511	  if (/owner|admin|approval|contact/.test(s)) return "Waiting for you to approve the confirmation email";
512	  if (/registry|processing|progress/.test(s)) return "Submitted to the registry";
513	  if (/complete|success|transferred/.test(s)) return "Completed";
514	  if (/cancel/.test(s)) return "Cancelled";
515	  if (/reject|denied/.test(s)) return "Rejected by the losing registrar";
516	  if (/expired/.test(s)) return "Expired — the confirmation was never approved";
517	  return status;
518	}
