543	export async function addRecord(
544	  domain: string,
545	  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
546	): Promise<void> {
547	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
