559	
560	/** Read-only view used by the DNS UI: apex host shown as "@". */
561	export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };
562	
563	export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
564	  const recs = await listRecords(domain);
565	  return recs.map((r) => ({
566	    name: r.host === "" ? "@" : r.host,
567	    type: r.type,
568	    address: r.answer,
569	    ttl: r.ttl,
