578	export type UrlForward = { host: string; forwardsTo: string; type: string };
579	
580	export async function listUrlForwarding(domain: string): Promise<UrlForward[]> {
581	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/url/forwarding`);
582	  return (json.urlForwarding ?? json.urlForwardings ?? []).map((f: any) => ({
583	    host: f.host ?? "",
584	    forwardsTo: f.forwardsTo ?? "",
585	    type: f.type ?? "redirect301",
586	  }));
587	}
588	
589	export async function addUrlForwarding(domain: string, fwd: UrlForward): Promise<void> {
590	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/url/forwarding`, fwd);
591	}
592	
593	export async function deleteUrlForwarding(domain: string, host: string): Promise<void> {
594	  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/url/forwarding/${encodeURIComponent(host)}`);
595	}
