17	function expiryTone(days: number | null): "green" | "amber" | "red" | "slate" {
18	  if (days === null) return "slate";
19	  if (days < 0) return "red";
20	  if (days <= 30) return "amber";
21	  return "green";
22	}
23	
24	function expiryLabel(d: Date | null): string {
25	  if (!d) return "—";
26	  const days = daysUntil(d);
27	  if (days < 0) return `expired ${-days}d ago`;
28	  if (days === 0) return "expires today";
29	  return `in ${days} day${days === 1 ? "" : "s"}`;
30	}
