35	function expiryNote(d: Date | null): { text: string; tone: "green" | "amber" | "red" | "slate" } {
36	  if (!d) return { text: "—", tone: "slate" };
37	  const days = daysUntil(d);
38	  if (days < 0) return { text: `expired ${-days} days ago`, tone: "red" };
39	  if (days === 0) return { text: "expires today", tone: "red" };
40	  if (days <= 30) return { text: `in ${days} days`, tone: "amber" };
41	  return { text: `in ${days} days`, tone: "green" };
42	}
