3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import {
8	  registrarConfigured,
9	  listRecords,
10	  addRecord,
11	  deleteRecord,
12	  type DnsRecord,
13	  lockDomain,
14	  unlockDomain,
15	  isDomainLocked,
16	  listUrlForwarding,
17	  addUrlForwarding,
