20	
21	/* ------------------------------------------------------------------ *
22	 * DNS super-manager actions for the customer domain manager.
23	 *
24	 * Reuses lib/registrar.ts's DNS helpers (listRecords/addRecord/
25	 * deleteRecord) for all record mutations, plus its URL-forwarding and
26	 * registrar-lock helpers. Everything is ownership-checked and degrades
27	 * gracefully (persist intent + a clear note) when the registrar isn't
28	 * configured or a TLD/endpoint isn't supported.
29	 * ------------------------------------------------------------------ */
30	
31	function errMsg(e: unknown): string {
32	  return String(e instanceof Error ? e.message : e).slice(0, 200);
33	}
34	
35	async function ownedDomain(domainId: string) {
36	  const user = await requireUser();
37	  const domain = await db.domain.findUnique({ where: { id: domainId } });
38	  if (!domain) throw new Error("Not found");
39	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
40	  return { user, domain };
41	}
42	
43	async function ownedActiveDomain(domainId: string) {
44	  const ctx = await ownedDomain(domainId);
45	  if (ctx.domain.status !== "ACTIVE") throw new Error("Domain is not active");
46	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
47	  return ctx;
48	}
49	
50	/* A record shape the client can build for presets / imports. Host "" = apex. */
51	export type RecordInput = {
52	  host: string;
53	  type: string;
54	  answer: string;
55	  ttl?: number;
56	  priority?: number;
57	};
58	
59	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
60	
61	function normHost(h: string): string {
62	  const t = (h ?? "").trim();
63	  return ["@", ""].includes(t) ? "" : t.replace(/\.$/, "");
64	}
65	
66	/** True if `want` is already present in `existing` (host+type+answer, MX also priority). */
67	function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
68	  const wh = normHost(want.host);
69	  const wa = want.answer.trim().toLowerCase();
70	  return existing.some((r) => {
71	    if (r.host !== wh) return false;
72	    if (r.type !== want.type) return false;
73	    if (r.answer.trim().toLowerCase() !== wa) return false;
74	    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
75	    return true;
76	  });
77	}
78	
79	const recordInputSchema = z.object({
80	  host: z.string().max(120).default(""),
81	  type: z.enum(RECORD_TYPES),
82	  answer: z.string().min(1).max(2000),
83	  ttl: z.coerce.number().int().min(60).max(86400).default(300),
84	  priority: z.coerce.number().int().min(0).max(65535).optional(),
85	});
86	
87	export type BulkResult = {
88	  error?: string;
89	  added?: string[];
90	  skipped?: string[];
91	  failed?: { record: string; reason: string }[];
92	  note?: string;
93	};
94	
95	function label(r: RecordInput): string {
96	  const h = normHost(r.host) || "@";
97	  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
98	  return `${r.type} ${h} → ${pri}${r.answer}`;
99	}
100	
101	/**
102	 * Add many DNS records at once, skipping any that already exist. Powers the
103	 * quick-setup presets and DNS import. Ownership-checked; domain must be ACTIVE.
104	 */
105	export async function addDnsRecordsBulk(
106	  domainId: string,
107	  records: RecordInput[]
108	): Promise<BulkResult> {
109	  let ctx;
110	  try {
111	    ctx = await ownedActiveDomain(domainId);
112	  } catch (e) {
113	    return { error: errMsg(e) };
114	  }
115	  if (!Array.isArray(records) || records.length === 0) return { error: "No records to add." };
116	  if (records.length > 100) return { error: "Too many records in one request (max 100)." };
117	
118	  const clean: RecordInput[] = [];
119	  for (const raw of records) {
120	    const parsed = recordInputSchema.safeParse(raw);
121	    if (!parsed.success) {
122	      return { error: `Invalid record: ${parsed.error.issues[0]?.message ?? "bad record"}` };
123	    }
124	    clean.push({ ...parsed.data, host: normHost(parsed.data.host) });
125	  }
126	
127	  let existing: DnsRecord[];
128	  try {
129	    existing = await listRecords(ctx.domain.name);
130	  } catch (e) {
131	    return { error: `Could not read current records: ${errMsg(e)}` };
132	  }
133	
134	  const added: string[] = [];
135	  const skipped: string[] = [];
136	  const failed: { record: string; reason: string }[] = [];
137	
138	  for (const rec of clean) {
139	    if (recordExists(existing, rec)) {
140	      skipped.push(label(rec));
141	      continue;
142	    }
143	    try {
144	      await addRecord(ctx.domain.name, {
145	        host: rec.host,
146	        type: rec.type,
147	        answer: rec.answer,
148	        ttl: rec.ttl ?? 300,
149	        priority: rec.type === "MX" || rec.type === "SRV" ? rec.priority ?? 10 : undefined,
150	      });
151	      added.push(label(rec));
152	      // Track locally so later records in the same batch dedupe correctly.
153	      existing.push({ id: -1, host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 300, priority: rec.priority });
154	    } catch (e) {
155	      failed.push({ record: label(rec), reason: errMsg(e) });
156	    }
157	  }
158	
159	  await db.auditLog.create({
160	    data: {
161	      userId: ctx.user.id,
162	      action: "domain.dns_bulk_add",
163	      detail: `${ctx.domain.name}: +${added.length} skip ${skipped.length} fail ${failed.length}`,
164	    },
165	  });
166	  revalidatePath(`/dashboard/domains/${domainId}`);
167	  return { added, skipped, failed: failed.length ? failed : undefined };
168	}
