170	/* ------------------------------------------------------------------ *
171	 * DNS import (paste) — CSV / zone-ish text: name,type,value[,ttl[,priority]]
172	 * Lines starting with # or ; are ignored. Whitespace or comma separated.
173	 * ------------------------------------------------------------------ */
174	
175	export type ParsedImport = { records: RecordInput[]; errors: string[] };
176	
177	/** Pure parser exported so the UI can preview before applying. */
178	export async function parseDnsImport(text: string): Promise<ParsedImport> {
179	  const records: RecordInput[] = [];
180	  const errors: string[] = [];
181	  const lines = (text ?? "").split(/\r?\n/);
182	  lines.forEach((line, i) => {
183	    const raw = line.trim();
184	    if (!raw || raw.startsWith("#") || raw.startsWith(";")) return;
185	    // split on comma OR whitespace, but keep the value token intact if quoted
186	    let parts: string[];
187	    if (raw.includes(",")) parts = raw.split(",").map((p) => p.trim());
188	    else parts = raw.split(/\s+/);
189	    if (parts.length < 3) {
190	      errors.push(`Line ${i + 1}: expected at least name, type, value`);
191	      return;
192	    }
193	    const [nameTok, typeTok, valueTok, ttlTok, prioTok] = parts;
194	    const type = typeTok.toUpperCase();
195	    if (!(RECORD_TYPES as readonly string[]).includes(type)) {
196	      errors.push(`Line ${i + 1}: unsupported type "${typeTok}"`);
197	      return;
198	    }
199	    const value = valueTok.replace(/^"|"$/g, "");
200	    const rec: RecordInput = { host: normHost(nameTok), type, answer: value };
201	    if (ttlTok && /^\d+$/.test(ttlTok)) rec.ttl = Math.min(86400, Math.max(60, Number(ttlTok)));
202	    if (type === "MX" && prioTok && /^\d+$/.test(prioTok)) rec.priority = Number(prioTok);
203	    records.push(rec);
204	  });
205	  return { records, errors };
206	}
