208	export async function importDnsRecords(domainId: string, text: string): Promise<BulkResult> {
209	  const { records, errors } = await parseDnsImport(text);
210	  if (errors.length && records.length === 0) {
211	    return { error: errors.join("; ").slice(0, 300) };
212	  }
213	  const res = await addDnsRecordsBulk(domainId, records);
214	  if (errors.length) {
215	    res.note = `${errors.length} line(s) skipped: ${errors.slice(0, 3).join("; ")}${errors.length > 3 ? "…" : ""}`;
216	  }
217	  return res;
218	}
