220	/* ------------------------------------------------------------------ *
221	 * Reset DNS to a sane default set (strong confirm handled in the UI).
222	 * Removes all customer-manageable records (A/AAAA/CNAME/TXT/MX/SRV/ALIAS),
223	 * leaves NS delegation untouched, then re-adds A @ / A www at the platform IP.
224	 * ------------------------------------------------------------------ */
225	
226	export async function resetDnsToDefaults(domainId: string): Promise<BulkResult> {
227	  let ctx;
228	  try {
229	    ctx = await ownedActiveDomain(domainId);
230	  } catch (e) {
231	    return { error: errMsg(e) };
232	  }
233	  const ip = process.env.PUBLIC_IP;
234	  const removable = new Set(["A", "AAAA", "CNAME", "TXT", "MX", "SRV", "ALIAS"]);
235	  let removed = 0;
236	  const failed: { record: string; reason: string }[] = [];
237	  try {
238	    const recs = await listRecords(ctx.domain.name);
239	    for (const r of recs) {
240	      if (!removable.has(r.type)) continue;
241	      try {
242	        await deleteRecord(ctx.domain.name, r.id);
243	        removed++;
244	      } catch (e) {
245	        failed.push({ record: `${r.type} ${r.host || "@"}`, reason: errMsg(e) });
246	      }
247	    }
248	  } catch (e) {
249	    return { error: `Could not read current records: ${errMsg(e)}` };
250	  }
251	
252	  const added: string[] = [];
253	  if (ip) {
254	    for (const host of ["", "www"]) {
255	      try {
256	        await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
257	        added.push(`A ${host || "@"} → ${ip}`);
258	      } catch (e) {
259	        failed.push({ record: `A ${host || "@"}`, reason: errMsg(e) });
260	      }
261	    }
262	  }
263	
264	  await db.auditLog.create({
265	    data: { userId: ctx.user.id, action: "domain.dns_reset", detail: `${ctx.domain.name}: removed ${removed}, added ${added.length}` },
266	  });
267	  revalidatePath(`/dashboard/domains/${domainId}`);
268	  return {
269	    added,
270	    skipped: [],
271	    failed: failed.length ? failed : undefined,
272	    note: `Removed ${removed} record(s)${added.length ? ` and restored a default A record set pointing at ${ip}` : " (no platform IP configured, so no default records were added)"}.`,
273	  };
274	}
