140	  let epp: string | null = domain.transferEpp ?? null;
141	  let unlocked = false;
142	  let registrarHit = false;
143	
144	  if (registrarConfigured()) {
145	    // Unlock — some TLDs can't be unlocked via API; don't hard-fail on this.
146	    try {
147	      await unlockDomain(domain.name);
148	      unlocked = true;
149	    } catch {
150	      /* lock state may be managed manually for this TLD */
151	    }
152	    // Retrieve the auth code.
153	    try {
154	      const code = await getAuthCode(domain.name);
155	      if (code) {
156	        epp = code;
157	        registrarHit = true;
158	      }
159	    } catch (e) {
160	      if (!epp) return { error: `Could not retrieve the auth code: ${errMsg(e)}` };
161	    }
162	  }
163	
164	  if (!epp) {
165	    return {
166	      error:
167	        "The transfer auth code isn't available yet — the registrar isn't connected. Please contact support to release this domain.",
168	    };
169	  }
170	
171	  await db.domain.update({ where: { id: domainId }, data: { transferEpp: epp } });
172	  await db.auditLog.create({
173	    data: {
174	      userId: user.id,
175	      action: "domain.transfer_out",
176	      detail: `${domainId} unlock=${unlocked} registrar=${registrarHit}`,
177	    },
178	  });
179	  revalidatePath(`/dashboard/domains/${domainId}`);
