35	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
36	
37	/* ------------------------------------------------------------------ *
38	 * Idempotency helpers
39	 *
40	 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
41	 * user+domain. Catches the double-click / impatient-retry case immediately and
42	 * keeps two concurrent requests from both reaching the registrar. Best-effort
43	 * only — it does not survive a restart or span multiple app instances.
44	 *
45	 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
46	 * charge+create runs in one `$transaction`, so a duplicate can never both take
47	 * money and create a second row. Renewal is guarded by an in-transaction expiry
48	 * re-check (charge and expiry advance together atomically).
49	 * ------------------------------------------------------------------ */
50	
51	const SUBMIT_GUARD_MS = 120_000;
52	const inFlightSubmits = new Map<string, number>();
53	
54	function beginSubmit(key: string): boolean {
55	  const now = Date.now();
56	  const heldUntil = inFlightSubmits.get(key);
57	  if (heldUntil !== undefined && heldUntil > now) return false;
58	  if (inFlightSubmits.size > 2000) {
59	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
60	  }
61	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
62	  return true;
63	}
64	
65	function endSubmit(key: string): void {
66	  inFlightSubmits.delete(key);
67	}
