80	/**
81	 * After a registrar call fails or times out we must NOT assume the registration
82	 * did not happen — name.com may well have taken the order. Ask the registrar
83	 * before touching the customer's money:
84	 *  - the domain is in our reseller account  -> registered (keep the charge)
85	 *  - the domain is still purchasable        -> not registered (safe to refund)
86	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
87	 */
88	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
89	  try {
90	    const info = await domainInfo(domain);
91	    return { state: "registered", expires: info.expires };
92	  } catch {
93	    /* not in our account, or the API is unhappy — fall through to availability */
94	  }
95	  try {
96	    const [check] = await checkDomains([domain]);
97	    if (check?.available === true) return { state: "not-registered" };
98	  } catch {
99	    /* registrar unreachable */
100	  }
101	  return { state: "unknown" };
102	}
