254	        where: { id: record.id },
255	        data: {
256	          status: "ACTIVE",
257	          registeredAt: new Date(),
258	          expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
259	          error: `Recovered after registrar error: ${reason}`.slice(0, 500),
260	        },
261	      });
262	      await db.auditLog.create({
263	        data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
264	      });
265	      await db.notification.create({
266	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
267	      });
268	      // Recovered-but-registered still counts as a successful registration —
269	      // it gets the same free inbox the happy path does.
270	      await setupDomainInboxEmail({
271	        userId: user.id,
272	        domainName: domain,
273	        expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
274	        mailboxLocalPart,
275	      });
276	      return { kind: "active", domainId: record.id };
277	    }
278	
279	    if (verdict.state === "not-registered") {
280	      // Confirmed still available at the registrar — refunding is safe.
281	      await db.$transaction([
282	        db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
283	        db.walletTransaction.create({
284	          data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
285	        }),
286	        db.domain.update({
287	          where: { id: record.id },
288	          data: { status: "FAILED", error: reason.slice(0, 500) },
289	        }),
290	      ]);
291	      return {
292	        kind: "refunded",
293	        domainId: record.id,
294	        message: `Registration failed: ${reason.slice(0, 200)} (you were refunded).`,
295	      };
296	    }
297	
298	    // Unknown: leave PENDING and charged, flag for manual review. Refunding
299	    // here risks giving away a domain we actually paid the registrar for.
300	    await db.domain.update({
301	      where: { id: record.id },
302	      data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
303	    });
304	    await db.auditLog.create({
305	      data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
306	    });
307	    await db.notification.create({
308	      data: {
309	        userId: user.id,
310	        title: `Domain ${domain} needs review`,
311	        body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
312	        href: `/dashboard/domains/${record.id}`,
313	      },
314	    });
315	    return {
316	      kind: "needs-review",
317	      domainId: record.id,
318	      message:
319	        `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
320	        `It is marked for review — do not retry, you will not be charged twice.`,
321	    };
322	  }
323	}
