325	export async function purchaseDomain(
326	  prev: any,
327	  formData: FormData,
328	): Promise<{ error?: string; checkout?: { clientSecret: string; publishableKey: string } }> {
329	  // Spend path: registering a domain debits the wallet AND buys a non-refundable
330	  // asset from a registrar in the customer's name, with registrant contact details
331	  // taken from this form. `submitTransferIn` — the same product, the same money —
332	  // has carried this guard since it was written; registration and renewal never did.
333	  await assertNotImpersonating();
334	  const user = await requireUser();
335	  // Purchase gate: an unverified address means we cannot reach the person we
336	  // are about to charge. See lib/email-verification.ts.
337	  const unverified = await emailVerificationError(user);
338	  if (unverified) return { error: unverified };
339	  // Feature flag: domain registration can be switched off platform-wide.
340	  if (!(await getSettingBool("feature_domains", true))) {
341	    return { error: "Domain registration is currently unavailable." };
342	  }
343	  if (!registrarConfigured()) {
344	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
345	  }
346	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
347	  // /dashboard/domains, captured into a cookie by PartnerSourceCapture). Read
