352	    firstName: z.string().min(1).max(60),
353	    lastName: z.string().min(1).max(60),
354	    address1: z.string().min(1).max(120),
355	    city: z.string().min(1).max(60),
356	    stateProvince: z.string().min(1).max(60),
357	    postalCode: z.string().min(1).max(20),
358	    country: z.string().length(2),
359	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
360	    email: z.string().email(),
361	  });
