371	  const contactParsed = contactSchema.safeParse({
372	    firstName: formData.get("firstName"),
373	    lastName: formData.get("lastName"),
374	    address1: formData.get("address1"),
375	    city: formData.get("city"),
376	    stateProvince: formData.get("stateProvince"),
377	    postalCode: formData.get("postalCode"),
378	    country: String(formData.get("country") ?? "").toUpperCase(),
379	    phone: formData.get("phone"),
380	    email: formData.get("email"),
381	  });
382	  if (!contactParsed.success) {
383	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
384	  }
385	  const contact = contactParsed.data as RegistrantContact;
386	
387	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
388	  // Also covers the card-shortfall branch below: that call only OPENS a Stripe
389	  // session (it doesn't touch the wallet or the registrar yet), so holding the
390	  // same guard just stops a double-click from opening two sessions for once
