393	  if (!beginSubmit(guardKey)) {
394	    return { error: "That registration is already being processed — give it a moment before retrying." };
395	  }
396	
397	  try {
398	    const existing = await db.domain.findUnique({ where: { name: domain } });
399	    if (existing) {
400	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
401	      if (existing.status === "PENDING") {
402	        return { error: "You already have a registration in progress for this domain." };
403	      }
404	      // FAILED means the earlier attempt never actually registered anything
405	      // and was already refunded (see the FAILED branch below/in
406	      // registerDomainCore) — nothing is owned under this name, so blocking a
407	      // retry here would contradict the platform's own promise ("you're never
408	      // charged for a name you don't get"). Real bug found live: a customer
409	      // hit a one-time registrar failure and then could never try that exact
410	      // domain again. Every other terminal status still blocks.
411	      if (existing.status !== "FAILED") {
412	        return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
413	      }
414	    }
415	
416	    // Live availability + retail(markup) & cost prices from name.com
417	    let priceCents: number; // retail per year (customer)
418	    let costCents: number; // registrar cost per year (us)
419	    try {
420	      const [check] = await checkDomains([domain]);
421	      if (!check) return { error: "Could not check availability. Try again." };
422	      if (!check.available) return { error: "Domain is not available." };
423	      if (check.premium) return { error: "Premium domains are not supported yet." };
424	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
