426	      costCents = check.costCents;
427	    } catch (e: any) {
428	      return { error: String(e?.message ?? e).slice(0, 200) };
429	    }
430	
431	    const totalCents = domainTermPriceCents(priceCents, dTerm.years);
432	    // Whether the customer opted to apply wallet balance at all (the wizard's
