449	      // SHORTFALL, mirroring payAndDeploy's wallet+card split (lib/actions.ts).
450	      // Nothing is charged or registered here; the actual registration only
451	      // happens once the card clears, via placeDomainCardOrder below.
452	      if (!stripeConfigured()) {
453	        return {
454	          error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}, and card payments aren't set up on this platform yet. Top up your wallet to continue.`,
455	        };
456	      }
457	      const priced: DomainOrderPrice = { priceCents, costCents };
458	      // Stash the registrant contact + frozen price BEFORE opening the session —
459	      // see DomainOrderIntent's doc comment in schema.prisma for why this can't
460	      // just ride in Stripe metadata like a VPS/hosting/email order's intent
461	      // does (a registrant contact has no combined length cap that fits
462	      // Stripe's 500-char-per-value limit).
463	      const stashed = await db.domainOrderIntent.create({
464	        data: {
465	          userId: user.id,
466	          domain,
467	          years: dTerm.years,
468	          firstName: contact.firstName,
469	          lastName: contact.lastName,
470	          address1: contact.address1,
471	          city: contact.city,
472	          stateProvince: contact.stateProvince,
473	          postalCode: contact.postalCode,
474	          country: contact.country,
475	          phone: contact.phone,
476	          email: contact.email,
477	          mailboxLocalPart,
478	          partnerSource: partnerSource ?? null,
479	          priceCents,
480	          costCents,
481	        },
482	      });
483	      let checkout;
484	      try {
485	        checkout = await createDomainOrderPaymentSession(user, cardCents, domain, dTerm.years, stashed.id, priced);
486	      } catch (e: any) {
