488	      }
489	      if (!checkout) {
490	        return { error: "Card payments aren't available right now. Top up your wallet to continue." };
491	      }
492	      return { checkout };
493	    }
494	
495	    // Wallet covers it — register immediately, exactly as this always has.
496	    let result: DomainRegistrationResult;
497	    try {
498	      result = await registerDomainCore(
499	        user,
500	        { domain, years: dTerm.years, contact, mailboxLocalPart, partnerSource: partnerSource ?? null },
