516	/**
517	 * Fulfil a domain registration paid by card — called only from
518	 * lib/fulfil-checkout.ts after the card leg is confirmed paid, exactly like
519	 * `placeHostingCardOrder`/`placeEmailCardOrder` (lib/actions-hosting.ts /
520	 * lib/actions-email-hosting.ts). Re-verifies EVERYTHING from the Stripe
521	 * session id alone — this file has `"use server"`, so this export is a
522	 * client-invokable Server Action, and it must trust nothing a caller supplies
523	 * except a session id that only Stripe itself could have produced as paid.
524	 *
525	 * The DomainOrderIntent row (not `purpose.sold`) is the authoritative source
526	 * for both the registrant contact and the frozen price — see that model's doc
527	 * comment in schema.prisma.
528	 */
529	export async function placeDomainCardOrder(
530	  sessionId: string,
531	): Promise<
532	  | { skip: true }
533	  | { error: string }
534	  | { domainId: string; kind: "active" }
535	  | { domainId: string; kind: "refunded" | "needs-review"; message: string }
536	> {
537	  const purpose = await getCheckoutPurpose(sessionId);
538	  if (purpose.kind !== "domainOrder") return { skip: true };
539	
540	  const [user, stashed] = await Promise.all([
541	    db.user.findUnique({ where: { id: purpose.userId } }),
542	    db.domainOrderIntent.findUnique({ where: { id: purpose.domainOrderId } }),
543	  ]);
544	  if (!user) return { error: "user not found for paid domain order" };
545	  if (!stashed) return { error: "domain order intent not found — it may already have been fulfilled and cleared" };
546	  // The row was written by THIS user's own purchaseDomain call, moments before
547	  // the session it is referenced from — a mismatch means the session's
548	  // metadata and the row it points at disagree about whose order this is,
549	  // which must never be trusted silently.
550	  if (stashed.userId !== purpose.userId) {
551	    return { error: `domain order intent ${stashed.id} belongs to a different user than the paid session` };
552	  }
553	
554	  const contact: RegistrantContact = {
555	    firstName: stashed.firstName,
556	    lastName: stashed.lastName,
557	    address1: stashed.address1,
558	    city: stashed.city,
559	    stateProvince: stashed.stateProvince,
560	    postalCode: stashed.postalCode,
561	    country: stashed.country,
562	    phone: stashed.phone,
563	    email: stashed.email,
564	  };
565	
566	  let result: DomainRegistrationResult;
567	  try {
568	    result = await registerDomainCore(
569	      user,
570	      {
571	        domain: stashed.domain,
572	        years: stashed.years,
573	        contact,
574	        mailboxLocalPart: stashed.mailboxLocalPart,
575	        partnerSource: stashed.partnerSource,
576	      },
577	      { priceCents: stashed.priceCents, costCents: stashed.costCents },
578	    );
579	  } catch (e) {
580	    if (e instanceof DomainOrderError) return { error: e.message };
581	    throw e;
582	  }
583	
584	  if (result.kind === "active") return { domainId: result.domainId, kind: "active" };
585	  return { domainId: result.domainId, kind: result.kind, message: result.message };
586	}
