588	/** A renewal already landed if the registrar expiry runs ~a month past ours. */
589	const RENEW_SLACK_MS = 30 * 86400_000;
590	
591	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
592	  // Spend path: a manual renewal debits the wallet and spends at the registrar.
593	  // See purchaseDomain above.
594	  await assertNotImpersonating();
595	  const user = await requireUser();
596	  // Purchase gate: a MANUAL renewal is a fresh spend decision. Automatic domain
597	  // renewal runs in the worker and does not come through here, so no existing
598	  // domain can lapse because of this check.
599	  const unverifiedRenew = await emailVerificationError(user);
600	  if (unverifiedRenew) return { error: unverifiedRenew };
601	  const domain = await db.domain.findUnique({ where: { id: domainId } });
602	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
603	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
604	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
605	
606	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
607	  const guardKey = `renew:${domain.userId}:${domain.name}`;
608	  if (!beginSubmit(guardKey)) {
609	    return { error: "A renewal for this domain is already in progress." };
610	  }
611	
612	  try {
613	    const dTerm = domainTerm(domain.termYears);
614	    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
615	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
616	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
617	
618	    const dbExpiry = domain.expiresAt ?? null;
619	
620	    // Idempotency: charge and expiry advance together in one transaction below,
621	    // so if the registrar expiry is already ahead of ours a previous attempt
622	    // renewed but never got charged/recorded. Adopt that renewal instead of
623	    // buying a second year.
624	    let registrarExpiry: Date | undefined;
625	    try {
626	      registrarExpiry = (await domainInfo(domain.name)).expires;
627	    } catch {
628	      /* non-fatal: fall through to a normal renew */
629	    }
630	    const alreadyRenewed =
631	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
632	
633	    if (!alreadyRenewed) {
634	      try {
635	        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
636	      } catch (e: any) {
637	        // The registrar call is the FIRST thing that happens, before any debit,
638	        // so "you have not been charged" is a fact here, not a hope — and saying
639	        // it stops a customer retrying a renewal they think half-succeeded.
640	        return {
641	          error:
642	            `The registrar refused to renew ${domain.name}: ${String(e?.message ?? e).slice(0, 200)}. ` +
643	            `Nothing has been charged. Wait a few minutes and try again; if it keeps failing, contact support with this message.`,
644	        };
645	      }
646	      registrarExpiry = await domainInfo(domain.name)
647	        .then((i) => i.expires)
648	        .catch(() => undefined);
649	    }
650	
651	    const targetExpiry =
652	      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);
653	
654	    try {
655	      const charged = await db.$transaction(async (tx) => {
656	        // Re-read under the transaction: if a concurrent request already advanced
657	        // the expiry it also already took the money — do not charge again.
658	        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
659	        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
660	          return false;
661	        }
662	        await debitWallet(tx, domain.userId, renewCents);
663	        await tx.walletTransaction.create({
664	          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
665	        });
666	        await tx.domain.update({
667	          where: { id: domainId },
668	          data: { expiresAt: targetExpiry, status: "ACTIVE" },
669	        });
670	        return true;
671	      });
672	      if (!charged) {
673	        revalidatePath(`/dashboard/domains/${domainId}`);
674	        return {};
675	      }
676	    } catch (e) {
677	      if (e instanceof InsufficientBalanceError) {
678	        // The registrar renewal already succeeded — flag the uncollected charge
679	        // instead of silently swallowing it.
680	        await db.auditLog
681	          .create({
682	            data: {
683	              userId: domain.userId,
684	              action: "domain.renew.uncharged",
685	              detail: `${domain.name}: renewed at registrar but wallet debit of ${renewCents}c failed`,
686	            },
687	          })
688	          .catch(() => {});
689	        return { error: "Insufficient balance." };
690	      }
691	      throw e;
692	    }
693	    revalidatePath(`/dashboard/domains/${domainId}`);
694	    return {};
695	  } finally {
696	    endSubmit(guardKey);
697	  }
698	}
