720	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
721	  const domainId = String(formData.get("domainId") ?? "");
722	  let ctx;
723	  try {
724	    ctx = await ownedDomain(domainId);
725	  } catch (e: any) {
726	    return { error: e.message };
727	  }
728	  const parsed = z
729	    .object({
730	      name: z.string().max(120).default(""),
731	      type: z.enum(RECORD_TYPES),
732	      address: z.string().min(1).max(500),
733	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
734	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
735	    })
736	    .safeParse({
737	      name: formData.get("name") ?? "",
738	      type: formData.get("type"),
739	      address: formData.get("address"),
740	      ttl: formData.get("ttl") || 300,
741	      mxPref: formData.get("mxPref") || undefined,
742	    });
743	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
744	
745	  // "@" or blank => apex (name.com uses empty host for apex)
746	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
747	  try {
748	    await addRecord(ctx.domain.name, {
749	      host,
750	      type: parsed.data.type,
751	      answer: parsed.data.address,
752	      ttl: parsed.data.ttl,
753	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
754	    });
755	  } catch (e: any) {
756	    // Say what the provider said AND what to do about it. A bare registrar
757	    // string ("422 Unprocessable Entity") tells a customer nothing they can act
758	    // on; this product's standard is that an error explains both halves.
759	    return {
760	      error:
761	        `Your DNS provider refused this record: ${String(e?.message ?? e).slice(0, 200)}. ` +
762	        `Check the value matches the record type (an A record needs an IPv4 address, a CNAME needs a hostname), ` +
763	        `then try again. Nothing was changed.`,
764	    };
765	  }
766	  revalidatePath(`/dashboard/domains/${domainId}`);
767	  return {};
768	}
769	
770	export async function deleteDnsRecord(
771	  domainId: string,
772	  record: { name: string; type: string; address: string }
773	): Promise<{ error?: string }> {
774	  let ctx;
775	  try {
776	    ctx = await ownedDomain(domainId);
777	  } catch (e: any) {
778	    return { error: e.message };
779	  }
780	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
781	  try {
782	    const recs = await listRecords(ctx.domain.name);
783	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
784	    if (!match) return { error: "Record not found (it may have already been removed). Refresh the page to see the current records." };
785	    await deleteRecord(ctx.domain.name, match.id);
786	  } catch (e: any) {
787	    return {
788	      error:
789	        `Your DNS provider refused to remove this record: ${String(e?.message ?? e).slice(0, 200)}. ` +
790	        `The record is still in place — refresh the page and try again in a moment.`,
791	    };
792	  }
793	  revalidatePath(`/dashboard/domains/${domainId}`);
794	  return {};
795	}
796	
797	/**
798	 * One-click: point apex + www at the platform's public IP.
799	 *
800	 * ADD BEFORE DELETE, per host. This used to delete every apex/www A record and
801	 * only then add the replacements — so a registrar hiccup, a rate limit or a
802	 * network blip in between took the domain DARK and left it that way, with an
803	 * error message that did not say the old records were already gone. That is the
804	 * "six domains dark while the run scored 4/4" failure shape: destructive work
805	 * done first, on the assumption the constructive half cannot fail.
806	 *
807	 * The new order is also idempotent — an A record already pointing at `ip` is
808	 * kept rather than churned — so clicking twice is free, and a half-finished run
809	 * can simply be retried.
810	 */
811	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
812	  let ctx;
813	  try {
814	    ctx = await ownedDomain(domainId);
815	  } catch (e: any) {
816	    return { error: e.message };
817	  }
818	  const ip = process.env.PUBLIC_IP;
819	  if (!ip) {
820	    return {
821	      error:
822	        "This platform doesn't have a public IP configured, so there is nothing to point the domain at. " +
823	        "Contact support — this is a platform configuration problem, not something you can fix from here.",
824	    };
825	  }
826	
827	  const done: string[] = [];
828	  try {
829	    const recs = await listRecords(ctx.domain.name);
830	    for (const host of ["", "www"]) {
831	      const label = host === "" ? ctx.domain.name : `www.${ctx.domain.name}`;
832	      const existing = recs.filter((r) => r.host === host && r.type === "A");
833	      const keep = existing.find((r) => r.answer === ip);
834	      // Constructive half FIRST: the name resolves somewhere at every instant.
835	      if (!keep) await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
836	      // Only now retire the records that point elsewhere.
837	      for (const r of existing) {
838	        if (keep && r.id === keep.id) continue;
839	        await deleteRecord(ctx.domain.name, r.id);
840	      }
841	      done.push(label);
842	    }
843	  } catch (e: any) {
844	    const reason = String(e?.message ?? e).slice(0, 200);
845	    return {
846	      error:
847	        `Your DNS provider rejected part of this change (${reason}). ` +
848	        (done.length > 0
849	          ? `${done.join(" and ")} ${done.length === 1 ? "was" : "were"} pointed at ${ip} and ${done.length === 1 ? "is" : "are"} live; the rest was not changed. `
850	          : "Nothing was changed and your existing records are untouched. ") +
851	        `Wait a minute and click Point at server again — it is safe to repeat.`,
852	    };
853	  }
854	  revalidatePath(`/dashboard/domains/${domainId}`);
855	  return {};
856	}
