1	/**
2	 * Shared money + state helpers for INBOUND domain transfers (transfer-in).
3	 *
4	 * Plain server-side module (no "use server") so both the server action
5	 * (lib/actions-domains-transfer.ts) and the worker sweep (worker/billing.ts)
6	 * settle a transfer through exactly the same code — one definition of "what the
7	 * customer paid" and one definition of "credit it back", so the two paths can
8	 * never disagree about the amount or double-credit the same transfer.
9	 */
10	
11	import { db } from "./db";
12	import { domainTermPriceCents } from "./billing-terms";
13	
14	/** A transfer buys the domain plus a 1-year extension — always a single year. */
15	export const TRANSFER_TERM_YEARS = 1;
16	
17	/**
18	 * ICANN's rule: a domain cannot be transferred within 60 days of its
19	 * registration or of a previous transfer. Surfaced in the pre-flight checklist.
20	 */
21	export const ICANN_TRANSFER_LOCK_DAYS = 60;
22	
23	/** Typical real-world duration of an inbound transfer. Never imply it's instant. */
24	export const TRANSFER_TYPICAL_DAYS = "5–7 days";
25	
26	/**
27	 * Give up on a transfer the registrar has stopped reporting on. Long enough to
28	 * cover the 5-7 day norm plus the registry's own auto-approval window.
29	 */
30	export const TRANSFER_STALE_DAYS = 14;
31	
32	/** Integer cents the customer is charged for transferring `domain` in. */
33	export function transferChargeCents(priceCents: number): number {
34	  return domainTermPriceCents(priceCents, TRANSFER_TERM_YEARS);
35	}
36	
37	/**
38	 * The exact charge description. Used verbatim at charge time AND to find the
39	 * invoice again when refunding, so the two always line up.
40	 */
41	export function transferChargeDescription(domain: string): string {
42	  return `Domain transfer in: ${domain} (includes 1 extra year)`;
43	}
44	
45	/* ------------------------------------------------------------------ *
46	 * Duplicate-submit guard (same shape as lib/actions-domains.ts).
47	 *
48	 * Layer 1 (here, in-process): stops a double-click or an impatient retry from
49	 * reaching the registrar twice. Best-effort — does not survive a restart.
50	 * Layer 2 (authoritative): `Domain.name` is UNIQUE and the row write happens
51	 * inside the same `$transaction` as the wallet debit, so a duplicate can never
52	 * both take money and create a second row.
53	 * ------------------------------------------------------------------ */
54	
55	const SUBMIT_GUARD_MS = 120_000;
56	const inFlight = new Map<string, number>();
57	
58	export function beginTransferSubmit(key: string): boolean {
59	  const now = Date.now();
60	  const heldUntil = inFlight.get(key);
61	  if (heldUntil !== undefined && heldUntil > now) return false;
62	  if (inFlight.size > 2000) {
63	    for (const [k, v] of inFlight) if (v <= now) inFlight.delete(k);
64	  }
65	  inFlight.set(key, now + SUBMIT_GUARD_MS);
66	  return true;
67	}
68	
69	export function endTransferSubmit(key: string): void {
70	  inFlight.delete(key);
71	}
72	
73	/* ------------------------------------------------------------------ *
74	 * Settlement
75	 * ------------------------------------------------------------------ */
76	
77	export type FailedTransferSettlement = {
78	  domainId: string;
79	  /** Raw registrar status to persist for display (null when we never got one). */
80	  transferStatus: string | null;
81	  /** Customer-facing reason, stored on `Domain.error`. */
82	  reason: string;
83	};
84	
85	/**
86	 * Terminal-fail an inbound transfer and credit back exactly what was charged.
87	 *
88	 * Idempotent by construction: the status change is a compare-and-swap from
89	 * TRANSFER_PENDING, and the credit only happens when that swap wins. A retried
90	 * sweep, a racing customer-initiated cancel, and a worker restart therefore all
91	 * converge on exactly ONE credit. Returns true when this call was the one that
92	 * settled it.
93	 *
94	 * Only call this once the money is genuinely owed back — i.e. the registrar has
95	 * confirmed the transfer failed or was cancelled. Never on an unknown state.
96	 */
97	export async function settleFailedTransferIn(s: FailedTransferSettlement): Promise<boolean> {
98	  const domain = await db.domain.findUnique({ where: { id: s.domainId } });
99	  if (!domain || domain.status !== "TRANSFER_PENDING") return false;
100	
101	  const refundCents = transferChargeCents(domain.priceCents);
102	  const description = transferChargeDescription(domain.name);
103	
104	  return db.$transaction(async (tx) => {
105	    const swapped = await tx.domain.updateMany({
106	      where: { id: s.domainId, status: "TRANSFER_PENDING" },
107	      data: {
108	        status: "TRANSFER_FAILED",
109	        transferStatus: s.transferStatus,
110	        error: s.reason.slice(0, 500),
111	        // The customer's credential at their old registrar is no longer needed.
112	        transferAuthCodeEnc: null,
113	      },
114	    });
115	    if (swapped.count === 0) return false; // someone else already settled it
116	
117	    if (refundCents > 0) {
118	      await tx.user.update({
119	        where: { id: domain.userId },
120	        data: { balanceCents: { increment: refundCents } },
121	      });
122	      await tx.walletTransaction.create({
123	        data: {
124	          userId: domain.userId,
125	          amountCents: refundCents,
126	          description: `Refund: transfer of ${domain.name} did not complete`,
127	        },
128	      });
129	      // Keep the ledger honest: the original PAID invoice becomes REFUNDED.
130	      // Matched on the exact description we stamped at charge time.
131	      await tx.invoice.updateMany({
132	        where: { userId: domain.userId, description, status: "PAID" },
133	        data: { status: "REFUNDED" },
134	      });
135	    }
136	    await tx.auditLog.create({
137	      data: {
138	        userId: domain.userId,
139	        action: "domain.transfer_in.refunded",
140	        detail: `${domain.name}: ${refundCents}c credited — ${s.reason}`.slice(0, 500),
141	      },
142	    });
143	    return true;
144	  });
145	}
146	
147	/**
148	 * Mark an inbound transfer complete: the domain is ours to manage now. Scrubs
149	 * the stored auth code — we keep someone else's registrar credential no longer
150	 * than the transfer needs it. CAS-guarded, so it lands exactly once.
151	 */
152	export async function settleCompletedTransferIn(opts: {
153	  domainId: string;
154	  transferStatus: string;
155	  registeredAt: Date | null;
156	  expiresAt: Date;
157	}): Promise<boolean> {
158	  const res = await db.domain.updateMany({
159	    where: { id: opts.domainId, status: "TRANSFER_PENDING" },
160	    data: {
161	      status: "ACTIVE",
162	      transferStatus: opts.transferStatus,
163	      transferAuthCodeEnc: null,
164	      error: null,
165	      ...(opts.registeredAt ? { registeredAt: opts.registeredAt } : {}),
166	      expiresAt: opts.expiresAt,
167	    },
168	  });
169	  return res.count > 0;
170	}
