import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, extname } from "node:path";
import { stripComments } from "./_source-tools.ts";

/**
 * A signed-in customer must never learn which registrar Nxeon uses behind the
 * scenes — search results, error messages, DNS/nameserver copy, and the AI
 * chat assistant all have to stay registrar-agnostic (see the multi-registrar
 * plan's leak list). This is a standing tripwire, not a one-time fix: it scans
 * every customer-facing surface for the literal registrar names and fails the
 * moment one shows up again, whether from a careless copy change or a future
 * registrar integration (Namecheap, eNom, ...).
 *
 * `app/admin/**` is excluded on purpose — the admin console is the ONE place
 * this information is allowed, and is expected, to appear (e.g. a per-domain
 * "Registrar" column).
 *
 * Comments are stripped before matching (via `stripComments`, same helper the
 * other structural tripwires use) so an internal doc comment explaining "this
 * calls name.com's API" doesn't fail the test — only text a customer could
 * actually see (JSX, string literals, template literals) counts.
 */

const ROOT = join(import.meta.dirname, "..");
const SCAN_DIRS = ["components/customer", "app/dashboard"];
const EXTENSIONS = new Set([".ts", ".tsx"]);

// Word-boundary on "enom" so it doesn't fire on ordinary English words that
// happen to contain that substring (e.g. "denominator", "phenomenon").
const FORBIDDEN: { label: string; pattern: RegExp }[] = [
  { label: "name.com", pattern: /name\.com/i },
  { label: "Namecheap", pattern: /namecheap/i },
  { label: "eNom", pattern: /\benom\b/i },
];

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) walk(full, out);
    else if (EXTENSIONS.has(extname(entry))) out.push(full);
  }
  return out;
}

test("no registrar identity leaks into customer-facing dashboard/components code", () => {
  const offenders: string[] = [];
  for (const dir of SCAN_DIRS) {
    for (const file of walk(join(ROOT, dir))) {
      const src = stripComments(readFileSync(file, "utf8"));
      const rel = file.slice(ROOT.length + 1);
      for (const { label, pattern } of FORBIDDEN) {
        if (pattern.test(src)) offenders.push(`${rel} — matched "${label}"`);
      }
    }
  }
  assert.deepEqual(
    offenders,
    [],
    `Registrar identity must never be visible to a signed-in customer, but found:\n${offenders.join("\n")}`
  );
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { RegistrarError, registrarSafeMessage } from "../lib/registrar.ts";

/**
 * REAL INCIDENT this exists to prevent: a registrar 402 ("name.com: Payment
 * failed") was shown to a customer verbatim, via `{ error: errMsg(e) }` at a
 * catch site with no idea the underlying error was registrar-attributed.
 * `RegistrarError` is the fix — its `customerMessage` is pattern-matched from
 * the raw text and is NEVER allowed to contain the registrar's name or the
 * registrar's own wording.
 */

test("RegistrarError never lets the registrar's name or raw text leak into customerMessage", () => {
  const e = new RegistrarError("namecom", "name.com: Payment failed — insufficient reseller balance");
  assert.equal(e.registrarId, "namecom");
  assert.equal(e.rawMessage, "name.com: Payment failed — insufficient reseller balance");
  assert.doesNotMatch(e.customerMessage.toLowerCase(), /name\.com|namecheap|enom/);
  assert.doesNotMatch(e.customerMessage, /reseller balance/i);
});

test("payment/balance-shaped failures map to the no-charge-made message", () => {
  for (const raw of [
    "Payment failed",
    "Insufficient balance on reseller account",
    "Card declined",
    "insufficient funds",
  ]) {
    const e = new RegistrarError("namecom", raw);
    assert.match(e.customerMessage, /no charge was made/i);
  }
});

test("everything else falls back to the hedged generic message (never asserts no charge happened)", () => {
  for (const raw of [
    "422 Unprocessable Entity",
    "DNS record already exists",
    "TLD not supported",
    "HTTP 500",
  ]) {
    const e = new RegistrarError("namecom", raw);
    // Hedged, not asserted: a DNS update isn't a payment, so the copy must not
    // flatly claim "no charge was made" for it.
    assert.match(e.customerMessage, /if this was a payment action/i);
  }
});

test("registrarSafeMessage extracts customerMessage from a RegistrarError and logs the raw text separately", () => {
  const e = new RegistrarError("namecom", "name.com: Payment failed");
  const original = console.error;
  const logged: unknown[][] = [];
  console.error = (...args: unknown[]) => logged.push(args);
  try {
    const safe = registrarSafeMessage(e);
    assert.doesNotMatch(safe, /name\.com/i);
    assert.equal(safe, e.customerMessage);
    // The raw, registrar-attributed text must still be visible to ops somewhere.
    assert.ok(logged.some((args) => args.join(" ").includes("Payment failed")));
  } finally {
    console.error = original;
  }
});

test("registrarSafeMessage falls back to the plain message for a non-registrar error", () => {
  assert.equal(registrarSafeMessage(new Error("Forbidden")), "Forbidden");
  assert.equal(registrarSafeMessage("plain string"), "plain string");
});

