+ * registrar-name-free message while still keeping the real failure for ops.
+ *
+ * `message` (inherited) stays the RAW text for anything that logs `e.message`
+ * without checking `instanceof` — `rawMessage` is the same value under an
+ * explicit name for call sites that DO check. `customerMessage` is the only
+ * one of the three ever allowed in front of a customer.
+ *
+ * The real production incident this exists for: a registrar 402 ("Payment
+ * failed") was shown to a customer verbatim, registrar name included, because
+ * every catch site just did `{ error: String(e.message) }`.
+ */
+export class RegistrarError extends Error {
+  readonly registrarId: string;
+  readonly rawMessage: string;
+  readonly customerMessage: string;
+
+  constructor(registrarId: string, rawMessage: string) {
+    super(rawMessage);
+    this.name = "RegistrarError";
+    this.registrarId = registrarId;
+    this.rawMessage = rawMessage;
+    this.customerMessage = classifyRegistrarFailure(rawMessage);
+  }
+}
+
+const PAYMENT_FAILURE_RE = /payment|balance|insufficient|declin|charge/i;
+
+/** Generic fallback — hedges "no charge" rather than asserting it, since not every call site is a payment. */
+const GENERIC_CUSTOMER_MESSAGE =
+  "Something went wrong on our end completing this request. No charge was made if this was a payment action; please try again or contact support.";
+
+const PAYMENT_CUSTOMER_MESSAGE =
+  "We couldn't complete this right now — no charge was made. Please try again or contact support.";
+
+/** Pattern-match a raw registrar error into a customer-safe category. Never echoes `raw`. */
+function classifyRegistrarFailure(raw: string): string {
+  return PAYMENT_FAILURE_RE.test(raw) ? PAYMENT_CUSTOMER_MESSAGE : GENERIC_CUSTOMER_MESSAGE;
+}
+
+/**
+ * Registrar-safe message for any caught error: `customerMessage` when it's a
+ * `RegistrarError`, otherwise the same raw-message-sliced behavior every catch
+ * site already used. Centralizing this means every call site that reads a
+ * caught registrar failure gets the fix by importing this instead of
+ * hand-rolling `String(e?.message ?? e)`.
+ *
+ * Also logs `rawMessage` + `registrarId` server-side (console.error, same
+ * mechanism this module already uses elsewhere) so a real failure is still
+ * diagnosable from the logs even though the customer never sees it — most of
+ * the ~15 call sites this replaces had no per-error logging of their own to
+ * hook into, so this is the one place that can guarantee it happens.
+ */
+export function registrarSafeMessage(e: unknown): string {
+  if (e instanceof RegistrarError) {
+    console.error(`[registrar:${e.registrarId}] ${e.rawMessage}`);
